def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The frame size determines the fill color.
    fill_for_size = {5: 8, 7: 4, 9: 3}

    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            height = r2 - r1 + 1
            if height not in fill_for_size:
                continue
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    width = c2 - c1 + 1
                    if width != height or width not in fill_for_size:
                        continue

                    if not (all(grid[r1][c] == 2 and grid[r2][c] == 2
                                for c in range(c1, c2 + 1)) and
                            all(grid[r][c1] == 2 and grid[r][c2] == 2
                                for r in range(r1, r2 + 1))):
                        continue

                    # Only fill frames whose interior contains a marker.
                    if not any(grid[r][c] == 2
                               for r in range(r1 + 1, r2)
                               for c in range(c1 + 1, c2)):
                        continue

                    color = fill_for_size[width]
                    for r in range(r1 + 1, r2):
                        for c in range(c1 + 1, c2):
                            if grid[r][c] == 0:
                                out[r][c] = color

    return out
